#include <bits/stdc++.h>
using namespace std;

int main() {
    string dummy;
    getline(cin, dummy);

    string line;
    getline(cin, line);
    stringstream ss(line);
    vector<string> arr;
    string x;
    while (ss >> x) arr.push_back(x);

    int cnt1 = 0;
    for (auto &s : arr) if (s == "1") cnt1++;

    int ans = 0;
    int cnt0 = 0;

    for (auto &s : arr) {
        if (s == "1") {
            ans = max(ans, cnt0 + cnt1);
            cnt1--;
        } else {
            cnt0++;
        }
    }

    cout << max(ans, cnt0 + cnt1) << endl;
    return 0;
}

