#include <bits/stdc++.h>
using namespace std;

int main() {
    string dummy;
    getline(cin, dummy);

    string line;
    getline(cin, line);
    stringstream ss(line);
    vector<char> arr;
    string token;
    while (ss >> token) {
        if (!token.empty())
            arr.push_back(token[0]);
    }

    int cnt1 = 0;
    for (char c : arr) {
        if (c == '1') cnt1++;
    }

    int ans = 0;
    int cnt0 = 0;

    for (char x : arr) {
        if (x == '1') {
            ans = max(ans, cnt0 + cnt1);
            cnt1 -= 1;
        } else {
            cnt0 += 1;
        }
    }

    cout << max(ans, cnt0 + cnt1) << endl;
    return 0;
}

